def min_available_duration(slots1, slots2, duration):
    slots1.sort()
    slots2.sort()
    i = j = 0
    while i < len(slots1) and j < len(slots2):
        lo = max(slots1[i][0], slots2[j][0])
        hi = min(slots1[i][1], slots2[j][1])
        if hi - lo >= duration:
            return [lo, lo + duration]
        # advance the slot that ends first
        if slots1[i][1] < slots2[j][1]:
            i += 1
        else:
            j += 1
    return []

#include <algorithm>

// Total area covered by two axis-aligned rectangles (A: ax1,ay1 - ax2,ay2; B likewise).
// Coordinates up to 1e4 in absolute value, so every area fits in int.
int computeArea(int ax1, int ay1, int ax2, int ay2,
                int bx1, int by1, int bx2, int by2) {
  int areaA = (ax2 - ax1) * (ay2 - ay1);
  int areaB = (bx2 - bx1) * (by2 - by1);
  // The overlap is the intersection of the x-intervals times the intersection of the y-intervals.
  int w = std::min(ax2, bx2) - std::max(ax1, bx1);
  int h = std::min(ay2, by2) - std::max(ay1, by1);
  int overlap = (w > 0 && h > 0) ? w * h : 0;   // no overlap if either side is <= 0
  return areaA + areaB - overlap;
}

vector<vector<int>> merge(vector<vector<int>>& intervals) {
    sort(intervals.begin(), intervals.end());   // by start, then end
    vector<vector<int>> out;
    for (const auto& cur : intervals) {
        if (out.empty() || out.back()[1] < cur[0])
            out.push_back(cur);                  // gap: start a new block
        else
            out.back()[1] = max(out.back()[1], cur[1]);  // overlap: extend
    }
    return out;
}

int minMeetingRooms(const vector<pair<int,int>>& meetings) {
    vector<int> starts, ends;
    for (auto [s, e] : meetings) { starts.push_back(s); ends.push_back(e); }
    sort(starts.begin(), starts.end());
    sort(ends.begin(), ends.end());
    int rooms = 0, best = 0;
    size_t j = 0;                       // next meeting to end
    for (int s : starts) {
        while (j < ends.size() && ends[j] <= s) { ++j; --rooms; }  // free first
        ++rooms;
        best = max(best, rooms);
    }
    return best;
}

int findMinArrowShots(vector<vector<int>>& points) {
    if (points.empty()) return 0;
    // Compare with <, never with a[1] - b[1] (overflows near INT_MIN/INT_MAX).
    sort(points.begin(), points.end(),
         [](const vector<int>& a, const vector<int>& b) { return a[1] < b[1]; });
    int arrows = 1;
    int pos = points[0][1];            // shoot at the earliest end
    for (const auto& p : points) {
        if (p[0] > pos) {              // this balloon starts after the arrow
            ++arrows;
            pos = p[1];
        }
    }
    return arrows;
}

// מפגשים חצי-פתוחים [start, end): [1,5] ו-[5,8] לא מתנגשים
bool canAttendAll(vector<vector<int>> meetings) {
    sort(meetings.begin(), meetings.end());            // לפי start
    for (size_t i = 1; i < meetings.size(); ++i)
        if (meetings[i][0] < meetings[i - 1][1])       // מתחיל לפני שהקודם נגמר
            return false;
    return true;
}

// schedules[e] = רשימת קטעי עבודה ממוינים ולא חופפים של עובד e. מחזיר את הפערים הסופיים
// (באורך חיובי) שבהם כולם פנויים, בסדר עולה.
vector<pair<int, int>> employeeFreeTime(const vector<vector<pair<int, int>>>& schedules) {
    using T = tuple<int, int, int>;                    // (start, עובד, אינדקס ברשימה שלו)
    priority_queue<T, vector<T>, greater<T>> pq;       // k-way merge לפי start
    for (int e = 0; e < (int)schedules.size(); ++e)
        if (!schedules[e].empty()) pq.push({schedules[e][0].first, e, 0});
    vector<pair<int, int>> out;
    bool started = false;
    int busyEnd = 0;
    while (!pq.empty()) {
        auto [s, e, i] = pq.top(); pq.pop();
        int end = schedules[e][i].second;
        if (started && s > busyEnd) out.push_back({busyEnd, s});   // פער: כולם פנויים
        busyEnd = started ? max(busyEnd, end) : end;
        started = true;
        if (i + 1 < (int)schedules[e].size()) pq.push({schedules[e][i + 1].first, e, i + 1});
    }
    return out;
}
